def is_majority(arr, n, x):
    # Find the first occurrence of x
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < x:
            lo = mid + 1
        else:
            hi = mid

    first = lo
    if first >= n or arr[first] != x:
        return False

    # Find the position just after the last occurrence of x
    lo, hi = first, n
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] <= x:
            lo = mid + 1
        else:
            hi = mid

    count = lo - first
    return count > n // 2


