class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def all_substrings(st: str):
            subs = [""]
            n = len(st)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    subs.append(st[i:j])
            return subs

        s_subs = all_substrings(s)
        t_subs = all_substrings(t)

        best = 0

        for left in s_subs:
            for right in t_subs:
                candidate = left + right
                if candidate == candidate[::-1]:
                    best = max(best, len(candidate))

        return best
