from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)

        # Segment tree size (next power of two)
        size = 1
        while size < n:
            size <<= 1

        # tree[i] stores the maximum remaining basket capacity in its range
        tree = [-1] * (2 * size)

        for i, cap in enumerate(baskets):
            tree[size + i] = cap

        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[i * 2], tree[i * 2 + 1])

        def find_first(need: int) -> int:
            """Return the leftmost available basket index with capacity >= need."""
            if tree[1] < need:
                return -1

            node = 1
            lo, hi = 0, size - 1

            while lo < hi:
                mid = (lo + hi) // 2
                left = node * 2

                if tree[left] >= need:
                    node = left
                    hi = mid
                else:
                    node = left + 1
                    lo = mid + 1

            return lo

        def remove(pos: int) -> None:
            """Mark basket at pos as used."""
            idx = size + pos
            tree[idx] = -1
            idx >>= 1

            while idx:
                tree[idx] = max(tree[idx * 2], tree[idx * 2 + 1])
                idx >>= 1

        unplaced = 0

        for fruit in fruits:
            pos = find_first(fruit)

            if pos == -1:
                unplaced += 1
            else:
                remove(pos)

        return unplaced
