            break

    second = None
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = pr + dr, pc + dc
        if 0 <= nr < n and 0 <= nc < n:
            if second is None or grid[nr][nc] < second:
                second = grid[nr][nc]

    return [1 if i % 2 == 0 else second for i in range(k)]
