from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        first_occ = {}
        for i, x in enumerate(elements):
            if x not in first_occ:
                first_occ[x] = i

        limit = max(groups)
        INF = 10**9
        best = [INF] * (limit + 1)

        for x, idx in first_occ.items():
            if x > limit:
                continue
            for value in range(x, limit + 1, x):
                if idx < best[value]:
                    best[value] = idx

        return [best[g] if best[g] != INF else -1 for g in groups]
