def is_Sub_Array(array, subarray):
    """
    Return True if `subarray` appears as a contiguous sublist/subarray of `array`.
    """
    n, m = len(array), len(subarray)

    # An empty list is a sublist of any list.
    if m == 0:
        return True

    if m > n:
        return False

    for i in range(n - m + 1):
        if array[i:i + m] == subarray:
            return True

    return False


if __name__ == "__main__":
    assert is_Sub_Array([1, 4, 3, 5], [1, 2]) == False
