from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [-1] * numberOfUsers

        # At the same timestamp, OFFLINE status changes must be processed
        # before any MESSAGE event.
        events = sorted(
            events,
            key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1)
        )

        for kind, timestamp, data in events:
            ts = int(timestamp)

            if kind == "OFFLINE":
                user = int(data)
                offline_until[user] = max(offline_until[user], ts + 60)
                continue

            # MESSAGE event
            for token in data.split():
                if token == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif token == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= ts:
                            mentions[i] += 1
                else:
                    # token has the form "id<number>"
                    user_id = int(token[2:])
                    mentions[user_id] += 1

        return mentions
