from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        ans = base

        for target in set(nums):
            if target == k:
                continue

            current = 0
            best_gain = 0

            for num in nums:
                if num == target:
                    current += 1
                elif num == k:
                    current -= 1

                if current < 0:
                    current = 0
                if current > best_gain:
                    best_gain = current

            ans = max(ans, base + best_gain)

        return ans
